SELECT 'chapter:catpope:1:de', 'chapter', 'catpope', 'de', '{"title":"Leugnen","author":"Mandy Mozart","number":1,"language":"de","release":"2025-10-04","status":"published","description":"Die Morgenroutine wird gestört","thumbnail":"images/s1c1-thumbnail.jpg","keyvisual":{"image":"images/s1c1-key-visual.webp","video":"videos/s1c1-key-visual.900w.mp4"},"audio":{"music":{"transitionDuration":3000,"defaultTrack":"calmness","tracks":[{"id":"calmness","path":"audio/music/s1c1-instrumental-brass-morton.128.mp3"},{"id":"tension","path":"audio/music/s1c2-instrumental.128.mp3"}]},"sampleLibrary":[{"id":"bells","path":"audio/samples/s1c1-bells.128.mp3"},{"id":"choir_loud","path":"audio/samples/s1c1-choir-loud-loud-loud.128.mp3"},{"id":"choir_once","path":"audio/samples/s1c1-choir-once-it-means-nothing.128.mp3"}]},"featuring":["catpope"],"groups":[{"label":"scenes-1-to-10","renderer":{"type":"vertical"},"interaction":"webtoon","slices":[{"image":"images/s1c1-key-visual.webp","width":390,"height":845,"video":{"src":"videos/s1c1-key-visual.900w.mp4"},"audio":{"music":{"tracks":[{"id":"calmness","volume":0.2},{"id":"tension","volume":0}]}}},{"image":"images/webtoon/s1c1/s1c1-slice-1.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-2.webp","width":390,"height":625,"dialog":[{"id":"s1c1-2-1","rect":{"x":7.78,"y":8.05,"width":84.53,"height":8.75},"text":"2 INT. SCHLAFZIMMER - NACHT","variant":"narration","size":4.15,"uppercase":true,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-2-2","rect":{"x":4.96,"y":29.49,"width":62.74,"height":11.63},"text":"EIN NEUER TAG,\\nEIN ALTES SPIEL!","variant":"narration","size":4.07,"uppercase":true,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-2-3","rect":{"x":47.78,"y":63.25,"width":36.84,"height":8.27},"text":"MAMA! WTF?","variant":"caption","size":4.11,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-3.webp","width":390,"height":625,"dialog":[{"id":"s1c1-3-1","rect":{"x":14.96,"y":49.65,"width":77.35,"height":9.55},"text":"Puh! Es war nur ein Traum.","variant":"caption","size":4.06,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-3-2","rect":{"x":0.09,"y":66.77,"width":99.91,"height":8.59},"text":"PLF schlief wieder ein.","variant":"narration","size":4.04,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-4.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-5.webp","width":390,"height":625,"audio":{"audio":{"samples":[{"id":"bells","trigger":{"type":"intersect","mode":"mono"},"volume":0.5,"delay":0}]}},"dialog":[{"id":"s1c1-5-1","rect":{"x":7.78,"y":-8.75,"width":84.53,"height":11.15},"text":"3 EXT. BRUTALISTISCHER WOHNBLOCK\\n- SONNENAUFGANG","variant":"narration","size":3.87,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-6.webp","width":390,"height":625,"dialog":[{"id":"s1c1-6-1","rect":{"x":7.78,"y":-38.99,"width":84.79,"height":46.03},"text":"An jedem Morgen ging die Sonne\\nauf, so war es geschrieben. Es\\nverschob sich, das wussten wir,\\nje nach Stellung der Erde zum\\nGestirn, und wenn es regnete oder\\nzu viel Nebel gab, dann konnten\\nwir dennoch sicher sein, dass es\\ndahinter, seit Beginn der Zeit,\\ndasselbe kosmische Ritual war.\\nAuf Schatten folgte Licht, und\\ndas Licht war das Leben, und mit\\ndem Leben begann auch mein Tag.","variant":"narration","size":3.77,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-7.webp","width":390,"height":625,"dialog":[{"id":"s1c1-7-1","rect":{"x":6.5,"y":38.45,"width":86.84,"height":21.39},"text":"Um dennoch sicherzugehen, dass\\ndieser Tag auch funktionieren\\nkonnte, stellte ich mir einen\\nWecker, einen digitalen mit\\nAtomuhrverbindung.","variant":"narration","size":3.85,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-7-2","rect":{"x":6.5,"y":67.89,"width":86.84,"height":7.63},"text":"4 BEZAHLWERBUNG - SIN TONIC","variant":"narration","size":3.87,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-8.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-9.webp","width":390,"height":625,"dialog":[{"id":"s1c1-9-1","rect":{"x":8.03,"y":29.01,"width":84.79,"height":10.99},"text":"5 INT. SCHLAFZIMMER -\\nSONNENAUFGANG","variant":"narration","size":3.83,"uppercase":true,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-9-2","rect":{"x":4.96,"y":52.85,"width":89.15,"height":24.43},"text":"Wir predigenden Wesen hatten die\\nPflicht, als erste vor den\\nGemein(d)en zu erscheinen und die\\neigenen Rituale vor diesen zu\\nerledigen. Daß gehörte eben\\ndazu...","variant":"narration","size":3.85,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-10.webp","width":390,"height":625,"dialog":[{"id":"s1c1-10-1","rect":{"x":23.16,"y":74.45,"width":66.32,"height":9.23},"text":"Es machte mir nichts aus.","variant":"narration","size":3.77,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-11.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-12.webp","width":390,"height":625,"dialog":[{"id":"s1c1-12-1","rect":{"x":5.47,"y":-42.51,"width":84.53,"height":50.51},"text":"Dennoch, ich war geübt darin,\\ndieses Ringen gekonnt zu\\nignorieren. Ja, geübt in\\nder Technik des Lucid Dreamings,\\neiner Methode, in der der\\nSchlummerzustand genutzt werden\\nkonnte, um die eigenen Träume zu\\nsteuern. Eine wahnsinnig\\nspannende Methode; es war, als\\nerlebte und schrieb man\\ngleichzeitig einen Film in\\naller Realität. Ein\\nunbeschreibliches\\nGefühl der Macht.","variant":"narration","size":3.86,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-13.webp","width":390,"height":625,"dialog":[{"id":"s1c1-13-1","rect":{"x":7.78,"y":-9.55,"width":85.56,"height":17.23},"text":"Ich zwang das Klingeln in ein\\nTrillern. Es vertausendfachte\\nsich wie bei einem\\nDMT Trip.","variant":"narration","size":3.86,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-14.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-15.webp","width":390,"height":625,"dialog":[{"id":"s1c1-15-1","rect":{"x":4.44,"y":-27.47,"width":90.94,"height":33.87},"text":"Ich verdichte diese weiter, bis sie\\nheulenden Siren wurden.\\nDie Siren nahm ich wiederum als\\nSample. Stabilisierte sie.\\nZeichnete mit ihnen eine\\nunsichtbare Schicht Engelhorn-\\nTrompeten in den Raum und brachte\\ndie Wolken in der obersten\\nHemisphäre zum Schwingen.","variant":"narration","size":3.84,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-16.webp","width":390,"height":625,"audio":{"music":{"tracks":[{"id":"calmness","volume":0.2},{"id":"tension","volume":0.5}]}}},{"image":"images/webtoon/s1c1/s1c1-slice-17.webp","width":390,"height":625,"dialog":[{"id":"s1c1-17-1","rect":{"x":3.93,"y":87.89,"width":48.63,"height":8.11},"text":"Zuerst zur Küche.","variant":"caption","size":3.8,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-18.webp","width":390,"height":625,"dialog":[{"id":"s1c1-18-1","rect":{"x":20.85,"y":65.01,"width":22.99,"height":8.11},"text":"Eiweis!","variant":"caption","size":3.5,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-18-2","rect":{"x":7.78,"y":79.09,"width":84.53,"height":8.11},"text":"6 INT. KÜCHE","variant":"caption","size":3.86,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-19.webp","width":390,"height":625,"dialog":[{"id":"s1c1-19-1","rect":{"x":7.78,"y":48.05,"width":84.53,"height":12.75},"text":"PLF schlug gekonnt zwei Eier\\nsynchron in einer Pfanne auf.","variant":"caption","size":3.81,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-20.webp","width":390,"height":625,"audio":{"music":{"tracks":[{"id":"calmness","volume":0}]}},"dialog":[{"id":"s1c1-20-1","rect":{"x":7.01,"y":37.81,"width":86.07,"height":20.59},"text":"Plötzliche Drehung. In der Luft\\nwaren Bremsspuren. Mit\\nhalb geschlossenen Augen ging PLF\\nins Klo. Nahm ein Buch.\\nSetzte sich.","variant":"caption","size":3.83,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-21.webp","width":390,"height":625,"dialog":[{"id":"s1c1-21-1","rect":{"x":7.78,"y":31.89,"width":84.53,"height":8.11},"text":"7 INT. KLO","variant":"caption","size":3.88,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-22.webp","width":390,"height":625,"dialog":[{"id":"s1c1-22-1","rect":{"x":34.96,"y":7.73,"width":57.35,"height":14.51},"text":"Nunja, bissi profan,\\ntaugt aber zum\\nGeschichten erzählen.","variant":"caption","size":3.79,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-22-2","rect":{"x":6.24,"y":71.57,"width":57.35,"height":14.51},"text":"Er machte drei Ringe\\nund gab einen an\\njeden Sohn?","variant":"caption","size":3.85,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-23.webp","width":390,"height":625,"dialog":[{"id":"s1c1-23-1","rect":{"x":51.62,"y":86.77,"width":44.53,"height":8.43},"text":"Dachte ich!","variant":"narration","size":4.06,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-24.webp","width":390,"height":625,"dialog":[{"id":"s1c1-24-1","rect":{"x":4.44,"y":60.05,"width":91.2,"height":34.03},"text":"Wer bestimmt die Wahrheit?\\nWer hält die Schlüssel zu den\\nGeschichten?\\nWo liegt der Unterschied zwischen\\nmeinem Wollen und dem, was ich für\\nandere inszeniere?\\nWem sollte ich dienen, wenn nicht\\ndrei Herren, der perfekten\\nDreieinigkeit des Chaos?","variant":"caption","size":3.86,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-25.webp","width":390,"height":625,"dialog":[{"id":"s1c1-25-1","rect":{"x":4.44,"y":25.81,"width":72.48,"height":31.47},"text":"Natürlich dauerte die\\nLektüre länger als ich es\\nwahrhaben wollte. Ich\\nneigte dazu, mich im Text\\nzu verlieren. Eingesaugt,\\nals wäre ich\\nselbst die Magd auf dem\\nScheiterhaufen.","variant":"narration","size":4.11,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-26.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-27.webp","width":390,"height":625,"audio":{"music":{"tracks":[{"id":"calmness","volume":0.1},{"id":"tension","volume":0.8}]}},"dialog":[{"id":"s1c1-27-1","rect":{"x":7.78,"y":16.53,"width":83.76,"height":12.59},"text":"Alles Fetisch? Alles Show?\\nWill ich nur unterhalten?","variant":"caption","size":4.11,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-28.webp","width":390,"height":625,"dialog":[{"id":"s1c1-28-1","rect":{"x":20.09,"y":7.25,"width":69.66,"height":25.39},"text":"Nein, es geht hier um\\nmehr als die\\nMetapher! Feuer\\nentzünden. Sie sollen\\nvor Emotionen mit mir\\nbrennen.","variant":"caption","size":4.12,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-29.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-30.webp","width":390,"height":625,"dialog":[{"id":"s1c1-30-1","rect":{"x":19.57,"y":73.96,"width":52.22,"height":3.66},"text":"Holy Moly, Guacamole!","variant":"bubble","font":"mono","size":4.05,"align":"left","valign":"top","mask":true,"maskShape":"rect","pad":0.3},{"id":"s1c1-30-2","rect":{"x":19.57,"y":77.22,"width":30,"height":3.66},"text":"Meine Eier!","variant":"bubble","font":"mono","size":4.05,"align":"left","valign":"top","mask":true,"maskShape":"rect","pad":0.3}]},{"image":"images/webtoon/s1c1/s1c1-slice-31.webp","width":390,"height":625,"audio":{"music":{"tracks":[{"id":"calmness","volume":0.2},{"id":"tension","volume":0}]}},"dialog":[{"id":"s1c1-31-1","rect":{"x":7.78,"y":33.17,"width":84.53,"height":8.11},"text":"8 INT. KÜCHE","variant":"caption","size":3.86,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-32.webp","width":390,"height":625,"dialog":[{"id":"s1c1-32-1","rect":{"x":13.16,"y":2.13,"width":54.53,"height":21.55},"text":"Ich ess später ein\\npaar Oblaten.\\n\\nEs gibt\\nWichtigeres...","variant":"caption","size":4.1,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-33.webp","width":390,"height":625,"dialog":[{"id":"s1c1-33-1","rect":{"x":46.24,"y":65.01,"width":48.38,"height":8.43},"text":"... die Routine!","variant":"caption","size":3.97,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-34.webp","width":390,"height":625,"dialog":[{"id":"s1c1-34-1","rect":{"x":7.78,"y":0.37,"width":84.53,"height":8.11},"text":"8 INT. BADEZIMMER","variant":"caption","size":3.86,"uppercase":true,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-34-2","rect":{"x":7.78,"y":18.77,"width":55.81,"height":22.35},"text":"Vorm Waschbecken\\nangekommen, ergriff\\nPLF die Paste –\\ndas blaue Elixier\\nextrudierte heraus.","variant":"caption","size":4.02,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-35.webp","width":390,"height":625,"dialog":[{"id":"s1c1-35-1","rect":{"x":43.42,"y":70.93,"width":54.53,"height":15.31},"text":"Verfehlt? WTF!\\nScheint ja gar nix\\nmehr zu klappen.","variant":"caption","size":4.11,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-36.webp","width":390,"height":625,"dialog":[{"id":"s1c1-36-1","rect":{"x":22.65,"y":71.25,"width":69.66,"height":11.47},"text":"Doch, beim zweite Versuch\\ngelang …","variant":"narration","size":3.97,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-36-2","rect":{"x":7.78,"y":84.69,"width":22.99,"height":8.43},"text":"Danke!","variant":"caption","size":3.87,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-37.webp","width":390,"height":625,"dialog":[{"id":"s1c1-37-1","rect":{"x":5.47,"y":53.01,"width":64.79,"height":18.35},"text":"WIR haben es\\nverstanden. Ruhe,\\njetzt, ich konzentriere\\nmich.","variant":"caption","size":3.97,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-38.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-39.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-40.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-41.webp","width":390,"height":625,"dialog":[{"id":"s1c1-41-1","rect":{"x":8.03,"y":60.53,"width":38.89,"height":8.27},"text":"Was war das?","variant":"caption","size":4.05,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-42.webp","width":390,"height":625,"dialog":[{"id":"s1c1-42-1","rect":{"x":17.52,"y":21.17,"width":66.84,"height":9.71},"text":"...","variant":"caption","size":4.05,"align":"center","mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-42-2","rect":{"x":8.03,"y":36.37,"width":38.89,"height":8.27},"text":"Es war da","variant":"caption","size":4.14,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-42-3","rect":{"x":20.09,"y":47.41,"width":17.09,"height":8.27},"text":"Wer","variant":"caption","size":4.05,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-42-4","rect":{"x":37.26,"y":59.41,"width":17.61,"height":8.27},"text":"Was","variant":"caption","size":4.05,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-42-5","rect":{"x":48.03,"y":72.21,"width":38.89,"height":10.51},"text":"wessen,\\nein Wesen!","variant":"caption","size":4.02,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-43.webp","width":390,"height":625,"dialog":[{"id":"s1c1-43-1","rect":{"x":8.03,"y":1.17,"width":45.3,"height":11.63},"text":"Ein Katzenvieh?\\nIm Bademantel?","variant":"caption","size":3.96,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-43-2","rect":{"x":3.76,"y":85.79,"width":94.19,"height":7.18},"text":"Nichts mehr! Wie es erschien, war es\\nauch wieder weg.","variant":"narration","frame":false,"size":4.11,"align":"left","valign":"top","mask":"#faf4f4","maskShape":"rect","pad":0.3}]},{"image":"images/webtoon/s1c1/s1c1-slice-44.webp","width":390,"height":625,"dialog":[{"id":"s1c1-44-1","rect":{"x":25.21,"y":73.65,"width":56.32,"height":14.99},"text":"Naja, gut, weg ist\\nsie, war wohl nur\\nEinbildung.","variant":"caption","size":4.1,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-45.webp","width":390,"height":625,"audio":{"audio":{"samples":[{"id":"choir_once","trigger":{"type":"intersect","mode":"mono"},"volume":0.8,"delay":0}]}}},{"image":"images/webtoon/s1c1/s1c1-slice-46.webp","width":390,"height":625,"dialog":[{"id":"s1c1-46-1","rect":{"x":7.78,"y":57.81,"width":84.53,"height":8.59},"text":"10 INT. KLEIDERKAMMER","variant":"caption","size":4.12,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-47.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-48.webp","width":390,"height":625,"dialog":[{"id":"s1c1-48-1","rect":{"x":8.29,"y":11.73,"width":60.68,"height":31.15},"text":"Sorgsam und mit\\ngeübter Hand glitt\\nich in die feine\\nGarbadine, deren\\nschlichtes Weiß ihre\\nfromme Eleganz\\nausstrahlte.","variant":"narration","size":4.11,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-49.webp","width":390,"height":625,"dialog":[{"id":"s1c1-49-1","rect":{"x":36.24,"y":45.97,"width":56.07,"height":52.27},"text":"Garbadine, mit\\nihrer diagonal\\ngerippten Struktur,\\nlag straff am\\nKörper an. Oft zu\\nUnrecht als\\ngewöhnlich\\nabgetan,\\nunterschied sie\\nsich wesentlich\\nvon der Popeline,\\ndie leichter und\\nquer gerippt\\nwar.","variant":"narration","size":4.04,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-50.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-51.webp","width":390,"height":625,"dialog":[{"id":"s1c1-51-1","rect":{"x":5.98,"y":35.57,"width":60.68,"height":22.35},"text":"Davon konnte ich mich\\njedoch nicht weiter\\nablenken lassen. Ich\\nliebte dieses\\nRitual.","variant":"narration","size":4.02,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-52.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-53.webp","width":390,"height":625,"dialog":[{"id":"s1c1-53-1","rect":{"x":52.91,"y":0.85,"width":38.12,"height":12.11},"text":"Das Binden\\nder Schnüre,","variant":"narration","size":3.97,"align":"right","mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-54.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-55.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-56.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-57.webp","width":390,"height":625,"dialog":[{"id":"s1c1-57-1","rect":{"x":22.39,"y":15.73,"width":59.15,"height":8.27},"text":"das Falten der Ärmel","variant":"narration","size":4.08,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-58.webp","width":390,"height":625,"dialog":[{"id":"s1c1-58-1","rect":{"x":27.52,"y":36.85,"width":65.04,"height":17.23},"text":"– alles saß. Ich fühlte\\nmich so rein wie der\\nStoff.","variant":"narration","size":3.98,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-59.webp","width":390,"height":625,"dialog":[{"id":"s1c1-59-1","rect":{"x":28.55,"y":54.29,"width":66.07,"height":27.79},"text":"Und so fromm und fein\\nwie die Nähte am\\nKorsett. Es war eine\\nmillimetergenaue\\nMaßanfertigung, die\\nmeine androidenhafte\\nGestalt glänzen ließ.","variant":"narration","size":4.1,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-59-2","rect":{"x":18.8,"y":84.21,"width":75.81,"height":8.59},"text":"Mein Einstieg in die Rolle!","variant":"narration","size":4.04,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-60.webp","width":390,"height":625,"dialog":[{"id":"s1c1-60-1","rect":{"x":4.96,"y":0.53,"width":84.27,"height":15.63},"text":"Nein, eine Rolle war es nicht\\nmehr. Die philosoph:innen\\nstritten sich über Identität.","variant":"caption","size":4.1,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-60-2","rect":{"x":7.78,"y":66.45,"width":84.53,"height":31.63},"text":"Ja, da war die Spiritualität/\\nTheologie\\nüberlegen. Endlich durchströmte\\nmich das am\\nheutigen Tag so lange auf sich\\nwarten lassende\\nSelbstbewusstsein. Ich war\\nbereit.","variant":"narration","size":3.98,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-61.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-62.webp","width":390,"height":625,"dialog":[{"id":"s1c1-62-1","rect":{"x":8.8,"y":92.2,"width":83.76,"height":3.68},"text":"PLF schritt in den Flur hinaus.","variant":"bubble","font":"mono","size":4.07,"align":"left","valign":"top","mask":true,"maskShape":"rect","pad":0.3}]},{"image":"images/webtoon/s1c1/s1c1-slice-63.webp","width":390,"height":625,"audio":{"audio":{"samples":[{"id":"bells","trigger":{"type":"click","mode":"poly","rect":{"y":31.7,"x":23.9,"width":51,"height":45.5}},"volume":0.6}]}}},{"image":"images/webtoon/s1c1/s1c1-slice-64.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-65.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-66.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-67.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-68.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-69.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-70.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-71.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-72.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-73.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-74.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-75.webp","width":390,"height":625,"dialog":[{"id":"s1c1-75-1","rect":{"x":15.21,"y":-32.27,"width":66.84,"height":42.51},"text":"Im Jahr als Mao Zedong\\nund Ulrike Meinhof zum\\nHerren aufstiegen,\\nkamen wir gemeinsam\\nhinunter. Die hatten\\nehrlich gesagt\\neigentlich\\npures Glück\\nüberhaupt in den Himmel\\nzu kommen. Schwer waren\\nsie zu interpretieren.","variant":"caption","size":3.93,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-76.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-77.webp","width":390,"height":625,"dialog":[{"id":"s1c1-77-1","rect":{"x":10.09,"y":1.65,"width":82.22,"height":23.15},"text":"Mit doppeltem Blick betrachten\\nmuss man solche Personen. Eine\\nJugend ohne Gott. Selber\\nwollten sie wohl zu Göttern\\nwerden. Konsequent waren sie.","variant":"caption","size":3.99,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-78.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-79.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-80.webp","width":390,"height":625,"dialog":[{"id":"s1c1-80-1","rect":{"x":7.01,"y":31.09,"width":85.3,"height":22.51},"text":"Das wäre schon eine tolle\\nGeschichte, oder nicht? Science\\nFiction passte damals einfach\\nwahnsinnig gut zu meinem\\nSelbstbild.","variant":"narration","size":4.02,"align":"right","mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-81.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-82.webp","width":390,"height":625,"dialog":[{"id":"s1c1-82-1","rect":{"x":13.16,"y":34.93,"width":61.2,"height":8.59},"text":"Da bist du ja wieder?","variant":"caption","size":4.05,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-83.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-84.webp","width":390,"height":625,"dialog":[{"id":"s1c1-84-1","rect":{"x":3.68,"y":57.33,"width":61.2,"height":11.47},"text":"Hau ab! Zieh Leine!\\nGeh du Untier!","variant":"caption","size":4.05,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-85.webp","width":390,"height":625,"dialog":[{"id":"s1c1-85-1","rect":{"x":8.55,"y":83.09,"width":61.2,"height":11.47},"text":"Und hässlich bist du\\nauch. OMG! Mon dieu!","variant":"caption","size":4.1,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-86.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-87.webp","width":390,"height":625,"dialog":[{"id":"s1c1-87-1","rect":{"x":18.8,"y":-19.79,"width":75.81,"height":79.15},"text":"KATZE zog sich zurück, als\\nhätte es die Schatten der\\nRealität unrechtmäßig\\nüberschritten, und wirbelte\\ndabei eine Wolke aus Staub\\nauf. In diesem Moment der\\nAbwehr überkam PLF ein\\nGefühl. Sie wurde erinnert\\nan die dystopischen\\nHeld:innen aus all den\\nErzählungen, von Sci-Fi bis\\nhin zu den tiefen der\\nheiligen Texte –\\nHeld:innen, die zuerst\\ngegen ihre inneren Dämonen\\nkämpfen mussten, um in\\neiner starren Welt ihre\\nwahre Identität zu finden.\\nNoch wusste PLF nicht, wie\\nsehr dieser Kampf nun auch\\nTeil ihrer eigenen Reise\\nwerden würde.","variant":"caption","size":4.04,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-88.webp","width":390,"height":625,"dialog":[{"id":"s1c1-88-1","rect":{"x":11.62,"y":72.37,"width":75.81,"height":21.23},"text":"PLF ging weiter und schritt\\ndurch die mäandernden Wege\\nder Siedlung wie Moses auf\\neinem Hoverboard durchs\\nRote Meer.","variant":"caption","size":4.04,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-89.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-90.webp","width":390,"height":625,"audio":{"audio":{"samples":[{"id":"choir_loud","trigger":{"type":"intersect","mode":"mono"},"volume":1,"delay":0}]}}},{"image":"images/webtoon/s1c1/s1c1-slice-91.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-92.webp","width":390,"height":625,"dialog":[{"id":"s1c1-92-1","rect":{"x":14.53,"y":43.55,"width":65.98,"height":17.53},"text":"Wie ein Sonnenstrahl\\nantwortete der Chor durch\\ndie dichten Wolken mit\\n„loud loud loud“, und es\\nwurde langsam heller.","variant":"bubble","font":"mono","size":4.1,"align":"left","valign":"top","mask":true,"maskShape":"rect","pad":0.3}]},{"image":"images/webtoon/s1c1/s1c1-slice-93.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-94.webp","width":390,"height":625,"audio":{"music":{"tracks":[{"id":"calmness","volume":0},{"id":"tension","volume":0}]}},"dialog":[{"id":"s1c1-94-1","rect":{"x":5.13,"y":50.13,"width":89.74,"height":28.27},"text":"Ende des 1. Kapitels\\n\\n---\\n\\n2. Kapitel “ÄRGER”\\n\\nVeröffentlichungstermin\\n1. November 2025","variant":"bubble","font":"mono","size":4.1,"align":"center","valign":"middle","mask":true,"maskShape":"rect","pad":0.3}]}]}]}', NULL, '2026-09-30 14:46:06', 'published', 'import' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `entity_versions` WHERE `entity_key` = 'chapter:catpope:1:de');
