SELECT 'chapter:catpope:2:de', 'chapter', 'catpope', 'de', '{"title":"Ärger","author":"Mandy Mozart","number":2,"language":"de","release":"2025-11-01","status":"draft","description":"Die Predigt wird gestört","thumbnail":"images/s1c2-thumbnail.jpg","keyvisual":{"image":"images/s1c2-key-visual.webp"},"featuring":["catpope"],"groups":[{"ref":{"src":"chapter2/scene-14.json"}},{"ref":{"src":"chapter2/scene-15.json"}},{"ref":{"src":"chapter2/scene-16.json"}},{"ref":{"src":"chapter2/scene-17.json"}},{"ref":{"src":"chapter2/scene-18.json"}},{"label":"scene-20","renderer":{"type":"vertical"},"interaction":"webtoon","slices":[{"image":"images/webtoon/s1c2/s1c2-slice-20.webp","width":390,"height":625,"dialog":[{"id":"s1c2-slice-23-narration","variant":"narration","rect":{"x":8,"y":4,"width":84,"height":52},"valign":"top","size":2.8,"text":["PLF betrat mit großen Schritten den Platz vor der Kathedrale.","Der Auftritt schien mit der Schönheit des Tempels konkurrieren zu wollen.","Ein Gefühlscocktail von Ehrfurcht, Stolz, Macht und Bestätigung durchströmte jedes Glied.","Man sah es PLF an: die ganze Statur war aufgereckt, jedes Glied stützte die Bögen, der Körper war kein organisches Gebilde aus Proteinen und Kohlenstoff mehr, sondern ein Geist, der zu schweben schien aus kosmischer Materie.","Erst einmal in Bewegung manifestierte sich das Werk.","Die Einsicht, die Zuversicht, mit der PLF das Gewand an diesen Ort trug, vervollständigte das Ganze.","Diese Kleider waren gemacht von Leuten für mächtige Leute."]}]},{"image":"images/webtoon/s1c2/s1c2-slice-21.webp","width":390,"height":625},{"image":"images/webtoon/s1c2/s1c2-slice-22.webp","width":390,"height":625}]}]}', NULL, '2026-09-30 14:46:06', 'published', 'import' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `entity_versions` WHERE `entity_key` = 'chapter:catpope:2:de');
