SELECT 'season:catpope:1:de', 'season', 'catpope', 'de', '{"title":"Das Erwachen","authors":["Mandy Mozart","Thomas Dalby"],"language":"de","number":1,"release":"2025-10-04","description":"Als die Morgenroutine einer narzisstischen religiösen Persönlichkeit durch eine mysteriöse Sphynx-Katze gestört wird, geraten sie in eine Spirale surrealer Begegnungen mit digitalen Verschwörungen, mythischen Kreaturen und glitchigen Realitäten, nur um schließlich zu entdecken, dass die Katze die ganze Zeit über ihre eigene gespaltene Identität war.","cover":{"square":"images/s1-cover-square.webp","portrait":"images/s1-cover-portrait.webp"},"download":{"music":"audio/CatPope-Awakening-Music.zip","image":"images/s1-music-vinyl.webp"},"supporters":[{"name":"SKE / austro mechana","logo":"images/supporters/ske.svg"},{"name":"Westbahnstudios","logo":"images/supporters/westbahnstudios.svg"},{"name":"Künstlerhof Frohnau","logo":"images/supporters/kuenstlerhof-frohnau.svg"}],"trailer":{"loop":"videos/s1-trailer-loop.1280w.mp4","sources":[{"src":"videos/s1-trailer-loop.1920w.mp4","media":"(min-width: 1600px)"}],"poster":"images/s1-trailer-poster.webp","chapter":0},"credits":{"artist":["Mandy Mozart","Thomas Dalby"],"writer":"Mandy Mozart","music":["Mandy Mozart","Nova Lux"],"sound":["Mandy Mozart","Nova Lux"]},"sequence":[{"type":"chapter","number":0,"status":"published"},{"type":"chapter","number":1,"status":"published"},{"type":"chapter","number":2,"status":"draft"},{"type":"chapter","number":3,"status":"coming-soon"},{"type":"chapter","number":4,"status":"coming-soon"},{"type":"chapter","number":5,"status":"coming-soon"}]}', NULL, '2026-10-01 11:54:18', 'published', 'import' FROM DUAL
