SELECT 'chapter:catpope:0:en', 'chapter', 'catpope', 'en', '{"title":"Roar Little Kitty","author":"Mandy Mozart","number":0,"language":"en","release":"2025-10-04","status":"published","description":"The prologue to season one.","thumbnail":"images/s1c0-thumbnail.webp","isPreview":true,"groups":[{"label":"roar-little-kitty","renderer":{"type":"vertical"},"slices":[{"image":"images/webtoon/s1c0/s1c0-slice-1.webp","width":390,"height":206,"video":{"src":"videos/roar-little-kitty.1080p.mp4","sources":[{"src":"videos/roar-little-kitty.480p.mp4","media":"(max-width: 600px)"},{"src":"videos/roar-little-kitty.720p.mp4","media":"(max-width: 1400px)"}],"player":true}}]}]}', NULL, '2026-10-01 11:04:58', 'published', 'import' FROM DUAL
