SELECT 'chapter:catpope:1:en', 'chapter', 'catpope', 'en', '{"title":"Denial","author":"Mandy Mozart","number":1,"language":"en","release":"2025-10-04","status":"published","description":"The morning routine is interrupted","thumbnail":"images/s1c1-thumbnail.jpg","keyvisual":{"image":"images/s1c1-key-visual.webp","video":"videos/s1c1-key-visual.900w.mp4"},"audio":{"music":{"transitionDuration":3000,"defaultTrack":"calmness","tracks":[{"id":"calmness","path":"audio/music/s1c1-instrumental-brass-morton.128.mp3"},{"id":"tension","path":"audio/music/s1c2-instrumental.128.mp3"}]},"sampleLibrary":[{"id":"bells","path":"audio/samples/s1c1-bells.128.mp3"},{"id":"choir_loud","path":"audio/samples/s1c1-choir-loud-loud-loud.128.mp3"},{"id":"choir_once","path":"audio/samples/s1c1-choir-once-it-means-nothing.128.mp3"}]},"featuring":["catpope"],"groups":[{"label":"scenes-1-to-10","renderer":{"type":"vertical"},"interaction":"webtoon","slices":[{"image":"images/s1c1-key-visual.webp","width":390,"height":845,"video":{"src":"videos/s1c1-key-visual.900w.mp4"},"audio":{"music":{"tracks":[{"id":"calmness","volume":0.2},{"id":"tension","volume":0}]}}},{"image":"images/webtoon/s1c1/s1c1-slice-1.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-2.webp","width":390,"height":625,"dialog":[{"id":"s1c1-2-1","rect":{"x":7.78,"y":8.05,"width":84.53,"height":8.75},"text":"2 INT. BEDROOM - NIGHT","variant":"narration","size":4.15,"uppercase":true,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-2-2","rect":{"x":4.96,"y":29.49,"width":62.74,"height":11.63},"text":"A NEW DAY,\\nTHE SAME OLD GAME!","variant":"narration","size":4.07,"uppercase":true,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-2-3","rect":{"x":47.78,"y":63.25,"width":36.84,"height":8.27},"text":"MOM! WTF?","variant":"caption","size":4.11,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-3.webp","width":390,"height":625,"dialog":[{"id":"s1c1-3-1","rect":{"x":14.96,"y":49.65,"width":77.35,"height":9.55},"text":"Phew! It was only a dream.","variant":"caption","size":4.06,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-3-2","rect":{"x":0.09,"y":66.77,"width":99.91,"height":8.59},"text":"PLF fell back asleep.","variant":"narration","size":4.04,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-4.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-5.webp","width":390,"height":625,"audio":{"samples":[{"id":"bells","trigger":{"type":"intersect","mode":"mono"},"volume":0.5,"delay":0}]},"dialog":[{"id":"s1c1-5-1","rect":{"x":7.78,"y":-8.75,"width":84.53,"height":11.15},"text":"3 EXT. BRUTALIST HOUSING BLOCK\\n- SUNRISE","variant":"narration","size":3.87,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-6.webp","width":390,"height":625,"dialog":[{"id":"s1c1-6-1","rect":{"x":7.78,"y":-38.99,"width":84.79,"height":46.03},"text":"Every morning the sun rose, so it was written. It shifted, we knew that, with the position of the Earth relative to its star, and when it rained or there was too much fog, we could still be sure that behind it all, since the beginning of time, the same cosmic ritual was taking place. Shadow was followed by light, and the light was life, and with life my day began too.","variant":"narration","size":3.77,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-7.webp","width":390,"height":625,"dialog":[{"id":"s1c1-7-1","rect":{"x":6.5,"y":38.45,"width":86.84,"height":21.39},"text":"Still, to make sure this day would actually work, I set myself an alarm clock, a digital one, synced to an atomic clock.","variant":"narration","size":3.85,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-7-2","rect":{"x":6.5,"y":67.89,"width":86.84,"height":7.63},"text":"4 PAID AD - SIN TONIC","variant":"narration","size":3.87,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-8.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-9.webp","width":390,"height":625,"dialog":[{"id":"s1c1-9-1","rect":{"x":8.03,"y":29.01,"width":84.79,"height":10.99},"text":"5 INT. BEDROOM -\\nSUNRISE","variant":"narration","size":3.83,"uppercase":true,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-9-2","rect":{"x":4.96,"y":52.85,"width":89.15,"height":24.43},"text":"We preaching beings had a duty to be the first to appear before the flock/folk and to perform our own rituals in front of them. That was just part of it...","variant":"narration","size":3.85,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-10.webp","width":390,"height":625,"dialog":[{"id":"s1c1-10-1","rect":{"x":23.16,"y":74.45,"width":66.32,"height":9.23},"text":"I didn\'t mind.","variant":"narration","size":3.77,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-11.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-12.webp","width":390,"height":625,"dialog":[{"id":"s1c1-12-1","rect":{"x":5.47,"y":-42.51,"width":84.53,"height":50.51},"text":"Still, I was well practiced at ignoring this ringing. Yes, practiced in the technique of lucid dreaming, a method in which the state of slumber could be used to steer your own dreams. An insanely exciting method; it was like living and writing a film at the same time, in full reality. An indescribable feeling of power.","variant":"narration","size":3.86,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-13.webp","width":390,"height":625,"dialog":[{"id":"s1c1-13-1","rect":{"x":7.78,"y":-9.55,"width":85.56,"height":17.23},"text":"I forced the ringing into a trill. It multiplied a thousandfold, like on a DMT trip.","variant":"narration","size":3.86,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-14.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-15.webp","width":390,"height":625,"dialog":[{"id":"s1c1-15-1","rect":{"x":4.44,"y":-27.47,"width":90.94,"height":33.87},"text":"I compressed it further until it became howling sirens.\\nI took the sirens in turn as a sample. Stabilized them. With them I drew an invisible layer of angel-horn trumpets into the room and set the clouds in the highest hemisphere vibrating.","variant":"narration","size":3.84,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-16.webp","width":390,"height":625,"audio":{"music":{"tracks":[{"id":"calmness","volume":0.2},{"id":"tension","volume":0.5}]}}},{"image":"images/webtoon/s1c1/s1c1-slice-17.webp","width":390,"height":625,"dialog":[{"id":"s1c1-17-1","rect":{"x":3.93,"y":87.89,"width":48.63,"height":8.11},"text":"Kitchen first.","variant":"caption","size":3.8,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-18.webp","width":390,"height":625,"dialog":[{"id":"s1c1-18-1","rect":{"x":20.85,"y":65.01,"width":25.16,"height":8.11},"text":"Protein!","variant":"caption","size":3.5,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-18-2","rect":{"x":7.78,"y":79.09,"width":84.53,"height":8.11},"text":"6 INT. KITCHEN","variant":"caption","size":3.86,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-19.webp","width":390,"height":625,"dialog":[{"id":"s1c1-19-1","rect":{"x":7.78,"y":48.05,"width":84.53,"height":12.75},"text":"PLF expertly cracked two eggs into a pan, perfectly in sync.","variant":"caption","size":3.81,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-20.webp","width":390,"height":625,"audio":{"music":{"tracks":[{"id":"calmness","volume":0}]}},"dialog":[{"id":"s1c1-20-1","rect":{"x":7.01,"y":37.81,"width":86.07,"height":20.59},"text":"A sudden turn. Skid marks in the air. Eyes half closed, PLF went to the loo. Took a book. Sat down.","variant":"caption","size":3.83,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-21.webp","width":390,"height":625,"dialog":[{"id":"s1c1-21-1","rect":{"x":7.78,"y":31.89,"width":84.53,"height":8.11},"text":"7 INT. LOO","variant":"caption","size":3.88,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-22.webp","width":390,"height":625,"dialog":[{"id":"s1c1-22-1","rect":{"x":34.96,"y":7.73,"width":57.35,"height":14.51},"text":"Well, a bit profane, but good for telling stories.","variant":"caption","size":3.79,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-22-2","rect":{"x":6.24,"y":71.57,"width":57.35,"height":14.51},"text":"He made three rings and gave one to each son?","variant":"caption","size":3.85,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-23.webp","width":390,"height":625,"dialog":[{"id":"s1c1-23-1","rect":{"x":51.62,"y":86.77,"width":44.53,"height":8.43},"text":"I knew it!","variant":"narration","size":4.06,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-24.webp","width":390,"height":625,"dialog":[{"id":"s1c1-24-1","rect":{"x":4.44,"y":60.05,"width":91.2,"height":34.03},"text":"Who decides what is true?\\nWho holds the keys to the stories?\\nWhere is the difference between what I want and what I stage for others?\\nWhom should I serve, if not three masters, the perfect trinity of chaos?","variant":"caption","size":3.86,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-25.webp","width":390,"height":625,"dialog":[{"id":"s1c1-25-1","rect":{"x":4.44,"y":25.81,"width":72.48,"height":31.47},"text":"Of course the reading took longer than I cared to admit. I tended to lose myself in the text. Sucked in, as if I myself were the maid on the pyre.","variant":"narration","size":4.11,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-26.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-27.webp","width":390,"height":625,"audio":{"music":{"tracks":[{"id":"calmness","volume":0.1},{"id":"tension","volume":0.8}]}},"dialog":[{"id":"s1c1-27-1","rect":{"x":7.78,"y":16.53,"width":83.76,"height":12.59},"text":"All fetish? All show?\\nDo I just want to entertain?","variant":"caption","size":4.11,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-28.webp","width":390,"height":625,"dialog":[{"id":"s1c1-28-1","rect":{"x":20.09,"y":7.25,"width":69.66,"height":25.39},"text":"No, this is about more than the metaphor! Light fires. They should burn with emotion, right along with me.","variant":"caption","size":4.12,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-29.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-30.webp","width":390,"height":625,"dialog":[{"id":"s1c1-30-1","rect":{"x":19.57,"y":73.96,"width":52.22,"height":3.66},"text":"Holy moly, guacamole!","variant":"bubble","font":"mono","size":4.05,"align":"left","valign":"top","mask":true,"maskShape":"rect","pad":0.3},{"id":"s1c1-30-2","rect":{"x":19.57,"y":77.22,"width":30,"height":3.66},"text":"My eggs!","variant":"bubble","font":"mono","size":4.05,"align":"left","valign":"top","mask":true,"maskShape":"rect","pad":0.3}]},{"image":"images/webtoon/s1c1/s1c1-slice-31.webp","width":390,"height":625,"audio":{"music":{"tracks":[{"id":"calmness","volume":0.2},{"id":"tension","volume":0}]}},"dialog":[{"id":"s1c1-31-1","rect":{"x":7.78,"y":33.17,"width":84.53,"height":8.11},"text":"8 INT. KITCHEN","variant":"caption","size":3.86,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-32.webp","width":390,"height":625,"dialog":[{"id":"s1c1-32-1","rect":{"x":13.16,"y":2.13,"width":54.53,"height":21.55},"text":"Communion wafers later.\\n\\nOther things matter more...","variant":"caption","size":4.1,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-33.webp","width":390,"height":625,"dialog":[{"id":"s1c1-33-1","rect":{"x":46.24,"y":65.01,"width":48.38,"height":8.43},"text":"... the routine!","variant":"caption","size":3.97,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-34.webp","width":390,"height":625,"dialog":[{"id":"s1c1-34-1","rect":{"x":7.78,"y":0.37,"width":84.53,"height":8.11},"text":"8 INT. BATHROOM","variant":"caption","size":3.86,"uppercase":true,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-34-2","rect":{"x":7.78,"y":18.77,"width":55.81,"height":22.35},"text":"Arriving at the sink, PLF grabbed the paste – the blue elixir came oozing out.","variant":"caption","size":4.02,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-35.webp","width":390,"height":625,"dialog":[{"id":"s1c1-35-1","rect":{"x":43.42,"y":70.93,"width":54.53,"height":15.31},"text":"Missed? WTF!\\nNothing seems to work anymore.","variant":"caption","size":4.11,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-36.webp","width":390,"height":625,"dialog":[{"id":"s1c1-36-1","rect":{"x":22.65,"y":71.25,"width":69.66,"height":11.47},"text":"Yes, the second attempt worked …","variant":"narration","size":3.97,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-36-2","rect":{"x":7.78,"y":84.69,"width":25.34,"height":8.43},"text":"Thanks!","variant":"caption","size":3.87,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-37.webp","width":390,"height":625,"dialog":[{"id":"s1c1-37-1","rect":{"x":5.47,"y":53.01,"width":64.79,"height":18.35},"text":"WE got it. Quiet now, I\'m concentrating.","variant":"caption","size":3.97,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-38.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-39.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-40.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-41.webp","width":390,"height":625,"dialog":[{"id":"s1c1-41-1","rect":{"x":8.03,"y":60.53,"width":43.83,"height":8.27},"text":"What was that?","variant":"caption","size":4.05,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-42.webp","width":390,"height":625,"dialog":[{"id":"s1c1-42-1","rect":{"x":17.52,"y":21.17,"width":66.84,"height":9.71},"text":"...","variant":"caption","size":4.05,"align":"center","mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-42-2","rect":{"x":8.03,"y":36.37,"width":39.71,"height":8.27},"text":"It was there","variant":"caption","size":4.14,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-42-3","rect":{"x":20.09,"y":47.41,"width":17.09,"height":8.27},"text":"Who","variant":"caption","size":4.05,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-42-4","rect":{"x":37.26,"y":59.41,"width":19.04,"height":8.27},"text":"What","variant":"caption","size":4.05,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-42-5","rect":{"x":48.03,"y":72.21,"width":38.89,"height":10.51},"text":"whose,\\na being!","variant":"caption","size":4.02,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-43.webp","width":390,"height":625,"dialog":[{"id":"s1c1-43-1","rect":{"x":8.03,"y":1.17,"width":45.3,"height":11.63},"text":"A cat beast?\\nIn a bathrobe?","variant":"caption","size":3.96,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-43-2","rect":{"x":3.76,"y":85.79,"width":94.19,"height":7.18},"text":"Nothing! Just as it appeared, it was gone again.","variant":"narration","frame":false,"size":4.11,"align":"left","valign":"top","mask":"#faf4f4","maskShape":"rect","pad":0.3}]},{"image":"images/webtoon/s1c1/s1c1-slice-44.webp","width":390,"height":625,"dialog":[{"id":"s1c1-44-1","rect":{"x":25.21,"y":73.65,"width":56.32,"height":14.99},"text":"Oh well, she\'s gone, probably just my imagination.","variant":"caption","size":4.1,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-45.webp","width":390,"height":625,"audio":{"samples":[{"id":"choir_once","trigger":{"type":"intersect","mode":"mono"},"volume":0.8,"delay":0}]}},{"image":"images/webtoon/s1c1/s1c1-slice-46.webp","width":390,"height":625,"dialog":[{"id":"s1c1-46-1","rect":{"x":7.78,"y":57.81,"width":84.53,"height":8.59},"text":"10 INT. VESTRY","variant":"caption","size":4.12,"uppercase":true,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-47.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-48.webp","width":390,"height":625,"dialog":[{"id":"s1c1-48-1","rect":{"x":8.29,"y":11.73,"width":60.68,"height":31.15},"text":"Carefully, with a practiced hand, I slipped into the fine gabardine, whose plain white radiated its pious elegance.","variant":"narration","size":4.11,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-49.webp","width":390,"height":625,"dialog":[{"id":"s1c1-49-1","rect":{"x":36.24,"y":45.97,"width":56.07,"height":52.27},"text":"Gabardine, with its diagonally ribbed weave, lay taut against the body. Often wrongly dismissed as ordinary, it differed significantly from poplin, which was lighter and ribbed crosswise.","variant":"narration","size":4.04,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-50.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-51.webp","width":390,"height":625,"dialog":[{"id":"s1c1-51-1","rect":{"x":5.98,"y":35.57,"width":60.68,"height":22.35},"text":"But I couldn\'t let that distract me any further. I loved this ritual.","variant":"narration","size":4.02,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-52.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-53.webp","width":390,"height":625,"dialog":[{"id":"s1c1-53-1","rect":{"x":52.91,"y":0.85,"width":38.12,"height":12.11},"text":"Tying\\nthe laces,","variant":"narration","size":3.97,"align":"right","mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-54.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-55.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-56.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-57.webp","width":390,"height":625,"dialog":[{"id":"s1c1-57-1","rect":{"x":22.39,"y":15.73,"width":59.15,"height":8.27},"text":"folding the sleeves","variant":"narration","size":4.08,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-58.webp","width":390,"height":625,"dialog":[{"id":"s1c1-58-1","rect":{"x":27.52,"y":36.85,"width":65.04,"height":17.23},"text":"– everything fit. I felt as pure as the fabric.","variant":"narration","size":3.98,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-59.webp","width":390,"height":625,"dialog":[{"id":"s1c1-59-1","rect":{"x":28.55,"y":54.29,"width":66.07,"height":27.79},"text":"As pious and fine as the seams of the corset. Tailored to the millimeter, it made my android-like figure shine.","variant":"narration","size":4.1,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-59-2","rect":{"x":18.8,"y":84.21,"width":75.81,"height":8.59},"text":"My way into the role!","variant":"narration","size":4.04,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-60.webp","width":390,"height":625,"dialog":[{"id":"s1c1-60-1","rect":{"x":4.96,"y":0.53,"width":84.27,"height":15.63},"text":"No, it was no longer a role. The philosophers were arguing about identity.","variant":"caption","size":4.1,"mask":true,"maskShape":"rect","pad":0},{"id":"s1c1-60-2","rect":{"x":7.78,"y":66.45,"width":84.53,"height":31.63},"text":"Yes, spirituality/theology had the upper hand there. At last the self-confidence I had waited for so long today flowed through me. I was ready.","variant":"narration","size":3.98,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-61.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-62.webp","width":390,"height":625,"dialog":[{"id":"s1c1-62-1","rect":{"x":8.8,"y":92.2,"width":83.76,"height":3.68},"text":"PLF strode out into the hallway.","variant":"bubble","font":"mono","size":4.07,"align":"left","valign":"top","mask":true,"maskShape":"rect","pad":0.3}]},{"image":"images/webtoon/s1c1/s1c1-slice-63.webp","width":390,"height":625,"audio":{"samples":[{"id":"bells","trigger":{"type":"click","mode":"poly","rect":{"x":33,"y":36,"width":30,"height":30}},"volume":0.6}]}},{"image":"images/webtoon/s1c1/s1c1-slice-64.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-65.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-66.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-67.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-68.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-69.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-70.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-71.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-72.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-73.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-74.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-75.webp","width":390,"height":625,"dialog":[{"id":"s1c1-75-1","rect":{"x":15.21,"y":-32.27,"width":66.84,"height":42.51},"text":"In the year Mao Zedong and Ulrike Meinhof ascended to the Lord, we came down together. Honestly, they were pretty lucky to make it into heaven at all. They were hard to interpret.","variant":"caption","size":3.93,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-76.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-77.webp","width":390,"height":625,"dialog":[{"id":"s1c1-77-1","rect":{"x":10.09,"y":1.65,"width":82.22,"height":23.15},"text":"People like that deserve a second look. A youth without God. They probably wanted to become gods themselves. Consistent, they were.","variant":"caption","size":3.99,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-78.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-79.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-80.webp","width":390,"height":625,"dialog":[{"id":"s1c1-80-1","rect":{"x":7.01,"y":31.09,"width":85.3,"height":22.51},"text":"That would make a great story, wouldn\'t it? Back then, science fiction just fit my self-image insanely well.","variant":"narration","size":4.02,"align":"right","mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-81.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-82.webp","width":390,"height":625,"dialog":[{"id":"s1c1-82-1","rect":{"x":13.16,"y":34.93,"width":61.2,"height":8.59},"text":"There you are again?","variant":"caption","size":4.05,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-83.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-84.webp","width":390,"height":625,"dialog":[{"id":"s1c1-84-1","rect":{"x":3.68,"y":57.33,"width":61.2,"height":11.47},"text":"Get lost! Beat it!\\nBegone, you beast!","variant":"caption","size":4.05,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-85.webp","width":390,"height":625,"dialog":[{"id":"s1c1-85-1","rect":{"x":8.55,"y":83.09,"width":61.2,"height":11.47},"text":"And you\'re ugly too.\\nOMG! Mon dieu!","variant":"caption","size":4.1,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-86.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-87.webp","width":390,"height":625,"dialog":[{"id":"s1c1-87-1","rect":{"x":18.8,"y":-19.79,"width":75.81,"height":79.15},"text":"CAT retreated, as if it had unlawfully crossed the shadows of reality, and stirred up a cloud of dust. In this moment of defense, a feeling came over PLF. They were reminded of the dystopian heroes of all the stories, from sci-fi to the depths of the holy texts – heroes who first had to fight their inner demons to find their true identity in a rigid world. PLF did not yet know how much this battle would now become part of their own journey.","variant":"caption","size":4.04,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-88.webp","width":390,"height":625,"dialog":[{"id":"s1c1-88-1","rect":{"x":11.62,"y":72.37,"width":75.81,"height":21.23},"text":"PLF walked on, striding through the meandering paths of the estate like Moses on a hoverboard through the Red Sea.","variant":"caption","size":4.04,"mask":true,"maskShape":"rect","pad":0}]},{"image":"images/webtoon/s1c1/s1c1-slice-89.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-90.webp","width":390,"height":625,"audio":{"samples":[{"id":"choir_loud","trigger":{"type":"intersect","mode":"mono"},"volume":1,"delay":0}]}},{"image":"images/webtoon/s1c1/s1c1-slice-91.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-92.webp","width":390,"height":625,"dialog":[{"id":"s1c1-92-1","rect":{"x":14.53,"y":43.55,"width":65.98,"height":17.53},"text":"Like a ray of sunshine, the choir answered through the thick clouds with “loud loud loud”, and it slowly grew brighter.","variant":"bubble","font":"mono","size":4.1,"align":"left","valign":"top","mask":true,"maskShape":"rect","pad":0.3}]},{"image":"images/webtoon/s1c1/s1c1-slice-93.webp","width":390,"height":625},{"image":"images/webtoon/s1c1/s1c1-slice-94.webp","width":390,"height":625,"audio":{"music":{"tracks":[{"id":"calmness","volume":0},{"id":"tension","volume":0}]}},"dialog":[{"id":"s1c1-94-1","rect":{"x":5.13,"y":50.13,"width":89.74,"height":28.27},"text":"End of Chapter 1\\n\\n---\\n\\nChapter 2 “ANGER”\\n\\nRelease date\\nNovember 1, 2025","variant":"bubble","font":"mono","size":4.1,"align":"center","valign":"middle","mask":true,"maskShape":"rect","pad":0.3}]}]}]}', NULL, '2026-09-30 14:46:06', 'published', 'import' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `entity_versions` WHERE `entity_key` = 'chapter:catpope:1:en');
